   768  blosc2_frame* blosc2_frame_from_sframe(uint8_t *sframe, int64_t len, bool copy) {
   769    // Get the length of the frame
   770    const uint8_t* header = sframe;
   771    int64_t frame_len;
   772    if (len < FRAME_HEADER_MINLEN) {
   773      return NULL;
   774    }
   775    swap_store(&frame_len, header + FRAME_LEN, sizeof(frame_len));
   776    if (frame_len != len) {   // sanity check
   777      return NULL;
   778    }
   779
   780    blosc2_frame* frame = calloc(1, sizeof(blosc2_frame));
   781    frame->len = frame_len;
   782
   783    // Now, the trailer length
   784    const uint8_t* trailer = sframe + frame_len - FRAME_TRAILER_MINLEN;
   785    int trailer_offset = FRAME_TRAILER_MINLEN - FRAME_TRAILER_LEN_OFFSET;
   786    if (trailer[trailer_offset - 1] != 0xce) {
   787      free(frame);
   788      return NULL;
   789    }
   790    uint32_t trailer_len;
   791    swap_store(&trailer_len, trailer + trailer_offset, sizeof(trailer_len));
   792    frame->trailer_len = trailer_len;
   793
   794    if (copy) {
   795      frame->sdata = malloc((size_t)len);
   796      memcpy(frame->sdata, sframe, (size_t)len);
   797    }
   798    else {
   799      frame->sdata = sframe;
   800    }
   801
   802    return frame;
   803  }
