   968  int frame_get_metalayers(blosc2_frame* frame, blosc2_schunk* schunk) {
   969    int32_t header_len;
   970    int64_t frame_len;
   971    int64_t frame_pos = FRAME_IDX_SIZE;
   972    int64_t nbytes;
   973    int64_t cbytes;
   974    int32_t chunksize;
   975    int32_t nchunks;
   976    int ret = get_header_info(frame, &header_len, &frame_len, &nbytes, &cbytes, &chunksize, &nchunks,
   977                              NULL, NULL, NULL, NULL, NULL);
   978    if (ret < 0) {
   979      fprintf(stderr, "Unable to get the header info from frame");
   980      return -1;
   981    }
   982
   983    // Get the header
   984    uint8_t* header = NULL;
   985    if (frame->sdata != NULL) {
   986      header = frame->sdata;
   987    } else {
   988      size_t rbytes = 0;
   989      header = malloc(header_len);
   990      FILE* fp = fopen(frame->fname, "rb");
   991      if (fp != NULL) {
   992        rbytes = fread(header, 1, header_len, fp);
   993        fclose(fp);
   994      }
   995      if (rbytes != (size_t) header_len) {
   996        fprintf(stderr, "Cannot access the header out of the fileframe.\n");
   997        free(header);
   998        return -2;
   999      }
  1000    }
  1001
  1002    // Get the size for the index of metalayers
  1003    uint16_t idx_size;
  1004    frame_pos += sizeof(idx_size);
  1005    if (frame_len < frame_pos) {
  1006      return -1;
  1007    }
  1008    swap_store(&idx_size, header + FRAME_IDX_SIZE, sizeof(idx_size));
  1009
  1010    // Get the actual index of metalayers
  1011    uint8_t* metalayers_idx = header + FRAME_IDX_SIZE + 2;
  1012    frame_pos += 1;
  1013    if (frame_len < frame_pos) {
  1014      return -1;
  1015    }
  1015    }
  1016    if (metalayers_idx[0] != 0xde) {   // sanity check
  1017      return -1;
  1018    }
  1019    uint8_t* idxp = metalayers_idx + 1;
  1020    uint16_t nmetalayers;
  1021    frame_pos += sizeof(nmetalayers);
  1022    if (frame_len < frame_pos) {
  1023      return -1;
  1024    }
  1025    swap_store(&nmetalayers, idxp, sizeof(uint16_t));
  1026    idxp += 2;
  1027    schunk->nmetalayers = nmetalayers;
  1028
  1029    // Populate the metalayers and its serialized values
  1030    for (int nmetalayer = 0; nmetalayer < nmetalayers; nmetalayer++) {
  1031      frame_pos += 1;
  1032      if (frame_len < frame_pos) {
  1033        return -1;
  1034      }
  1035      if ((*idxp & 0xe0u) != 0xa0u) {   // sanity check
  1036        return -1;
  1037      }
  1038      blosc2_metalayer* metalayer = calloc(sizeof(blosc2_metalayer), 1);
  1039      schunk->metalayers[nmetalayer] = metalayer;
  1040
  1041      // Populate the metalayer string
  1042      int8_t nslen = *idxp & (uint8_t)0x1F;
  1043      idxp += 1;
  1044      frame_pos += nslen;
  1045      if (frame_len < frame_pos) {
  1046        return -1;
  1047      }
  1048      char* ns = malloc((size_t)nslen + 1);
  1049      memcpy(ns, idxp, nslen);
  1050      ns[nslen] = '\0';
  1051      idxp += nslen;
