  1053
  1054      // Populate the serialized value for this metalayer
  1055      // Get the offset
  1056      frame_pos += 1;
  1057      if (frame_len < frame_pos) {
  1058        return -1;
  1059      }
  1060      if ((*idxp & 0xffu) != 0xd2u) {   // sanity check
  1061        return -1;
  1062      }
  1063      idxp += 1;
  1064      int32_t offset;
  1065      frame_pos += sizeof(offset);
  1066      if (frame_len < frame_pos) {
  1067        return -1;
  1068      }
  1069      swap_store(&offset, idxp, sizeof(offset));
  1070      idxp += 4;
