  1073      uint8_t* content_marker = header + offset;
  1074      if (*content_marker != 0xc6) {
  1075        return -1;
  1076      }
  1077
  1078      // Read the size of the content
  1079      int32_t content_len;
  1080      frame_pos += sizeof(content_len);
  1081      if (frame_len < frame_pos) {
  1082        return -1;
  1083      }
  1084      swap_store(&content_len, content_marker + 1, sizeof(content_len));
  1085      metalayer->content_len = content_len;
  1086
  1087      // Finally, read the content
  1088      frame_pos += content_len;
  1089      if (frame_len < frame_pos) {
  1090        return -1;
  1091      }
  1092      char* content = malloc((size_t)content_len);
  1093      memcpy(content, content_marker + 1 + 4, (size_t)content_len);
  1094      metalayer->content = (uint8_t*)content;
  1095    }
  1096
  1097    if (frame->sdata == NULL) {
  1098      free(header);
  1099    }
  1100    return 1;
  1101  }
