   593      uint8_t* data_chunk = schunk->data[i];
   594      int32_t chunk_cbytes = sw32_(data_chunk + BLOSC2_CHUNK_CBYTES);
   595      data_tmp[i] = coffset;
   596      coffset += chunk_cbytes;
